/**
 * @name Path traversal from S3 keys to file operations
 * @description S3 object keys used in file paths without validation may allow directory traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-key-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module KeyPathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters that might receive S3 keys or filenames
    exists(DataFlow::ParameterNode param |
      param.getParameter().getName() in ["key", "filename", "fileobj", "s3_key", "bucket_key", "extra_args"] and
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember(["makedirs", "mkdir", "remove", "unlink", "rmdir"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module KeyPathTraversalFlow = TaintTracking::Global<KeyPathTraversalConfig>;
import KeyPathTraversalFlow::PathGraph

from KeyPathTraversalFlow::PathNode source, KeyPathTraversalFlow::PathNode sink
where KeyPathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal: S3 key parameter flows to file operation $@.", source.getNode(), "source"

/**
 * @name Command injection via subprocess
 * @description Using subprocess with shell=True and untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from untrusted parameter $@.", source.getNode(), "source"
